$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$art=Join-Path $root 'artifacts';$h=Join-Path $art 'integrated-project-check'
$proofPath=Join-Path $art 'integrated-project-archive-verification.json';$proof=Get-Content -LiteralPath $proofPath -Raw|ConvertFrom-Json;if($proof.status -ne 'PASS'){throw 'Verified release required'}
$forward=Get-Content -LiteralPath (Join-Path $h 'forward-result.json') -Raw|ConvertFrom-Json;$reverse=Get-Content -LiteralPath (Join-Path $h 'reverse-result.json') -Raw|ConvertFrom-Json
$lease=[IO.File]::Open((Join-Path $art 'offline-editor-runtime.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
try{
 $failed=Join-Path $h 'Forward/PROJECT-5db4293c422d';$diagnostics=Join-Path $failed 'failed-build-sources';New-Item -ItemType Directory -Path $diagnostics -Force|Out-Null
 foreach($pair in @(@('Target/Source','Host'),@('Target/Plugins/EMActorPort/Source','ActorPort'),@('Target/Plugins/EMIntegrationProbe/Source','Probe'))){$sourcePath=Join-Path $failed $pair[0];if(Test-Path -LiteralPath $sourcePath){Copy-Item -LiteralPath $sourcePath -Destination (Join-Path $diagnostics $pair[1]) -Recurse -Force}}
 $targets=@($proof.unicodeExtraction,(Join-Path $failed 'Source'),(Join-Path $failed 'Target'),(Join-Path $h 'UnityTemplate/Library'),(Join-Path $forward.SourceCopy 'Library'))
 foreach($project in @((Join-Path $h 'UnityInput'),$reverse.TargetCopy)){$library=Join-Path $project 'Library';if(Test-Path -LiteralPath $library){foreach($d in Get-ChildItem -LiteralPath $library -Directory -Force){if($d.Name -notin @('PackageCache','PackageManager')){$targets+=$d.FullName}}}}
 $old=Join-Path $art 'EngineMigrator-late-lifecycle-preview-20261024';$running=@(Get-Process EngineMigrator.App -ErrorAction SilentlyContinue);$preservedRunning=@()
 if(Test-Path -LiteralPath $old){if(@($running|Where-Object{-not $_.Path -or $_.Path.StartsWith($old+'\',[StringComparison]::OrdinalIgnoreCase)}).Count){$preservedRunning+=$old}else{$targets+=$old;if(Test-Path -LiteralPath ($old+'.zip')){$targets+=($old+'.zip')}}}
 $entries=@()
 foreach($p in $targets|Sort-Object -Unique){if(-not(Test-Path -LiteralPath $p)){continue};$full=[IO.Path]::GetFullPath($p);if(-not $full.StartsWith($art+'\',[StringComparison]::OrdinalIgnoreCase)){throw "Outside artifacts: $full"};$item=Get-Item -LiteralPath $full -Force;$cursor=$item;while($cursor){if($cursor.Attributes -band [IO.FileAttributes]::ReparsePoint){throw "Reparse ancestor: $full"};if($cursor.FullName -eq $root){break};$cursor=Get-Item -LiteralPath (Split-Path -Parent $cursor.FullName) -Force};$content=if($item.PSIsContainer){@(Get-ChildItem -LiteralPath $full -Recurse -Force)}else{@($item)};if(@($content|Where-Object{$_.Attributes -band [IO.FileAttributes]::ReparsePoint}).Count){throw "Nested reparse: $full"};$entries+=[pscustomobject]@{path=$full;bytes=[long](($content|Where-Object{-not $_.PSIsContainer}|Measure-Object Length -Sum).Sum)}}
 $report=[ordered]@{status='VALIDATED';targets=$entries;deletedBytes=0;preservedRunning=$preservedRunning;preserved='Latest/fallback releases, successful native/restored projects, input runtime sources, captures, transfer packages, receipts, failed compile sources/logs and offline package caches'};$manifest=Join-Path $h 'cleanup.json';$report|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $manifest -Encoding utf8
 foreach($entry in $entries){Remove-Item -LiteralPath $entry.path -Recurse -Force;if(Test-Path -LiteralPath $entry.path){throw "Incomplete deletion: $($entry.path)"};$report.deletedBytes+=$entry.bytes}
 $proof|Add-Member -NotePropertyName temporaryExtractionRemoved -NotePropertyValue $true -Force;$proof|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $proofPath -Encoding utf8;$report.status='PASS';$report.completedKst=[DateTimeOffset]::UtcNow.ToOffset([TimeSpan]::FromHours(9)).ToString('o');$report|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $manifest -Encoding utf8;Write-Output ('INTEGRATED_CLEANUP_PASS removedGiB={0:N3} targets={1}'-f($report.deletedBytes/1GB),$entries.Count)
}finally{$lease.Dispose()}
